#include <iostream>
using namespace std;
long long N, K;
const long long MOD = 1000000007;
long long Power[65], Res[35][35];
long long S[65][35][35][35], A[65][35][35][35], P[65][35][35][35], Aux[35][35];
pair <long long, long long> X[105];

void copy_matrix(long long dest[][35], long long src[][35], long long size) {
    for (long long i = 0; i < size; i++)
        for (long long j = 0; j < size; j++)
            dest[i][j] = src[i][j];
}

inline void mod_add(long long& x, long long y) {
    x += y;
    if (x >= MOD) x -= MOD;
}

void matrix_multiply_func(long long A[][35], long long B[][35], long long C[][35], long long n, long long m, long long p) {
    for (long long i = 0; i < n; i++)
        for (long long j = 0; j < p; j++) {
            C[i][j] = 0;
            for (long long k = 0; k < m; k++)
                mod_add(C[i][j], (A[i][k] * B[k][j]) % MOD);
        }
}

void initializeA() {
    for (long long x = 0; x < K; x++) {
        for (long long i = 0; i < K + 1; i++) A[0][x][i][i] = 1;
        for (long long j = 0; j < K + 1; j++) A[0][x][j][x] = 1;
    }
    copy_matrix(P[0][0], A[0][0], K + 1);
    copy_matrix(S[0][K - 1], A[0][K - 1], K + 1);
    for (long long x = 1; x < K; x++)
        matrix_multiply_func(P[0][x - 1], A[0][x], P[0][x], K + 1, K + 1, K + 1);
    for (long long x = K - 2; x >= 0; x--)
        matrix_multiply_func(A[0][x], S[0][x + 1], S[0][x], K + 1, K + 1, K + 1);
    long long count = 1;
    for (long long m = K; m <= N; m *= K, count++) {
        for (long long x = 0; x < K; x++) {
            if (x > 0) {
                copy_matrix(A[count][x], S[count - 1][x], K + 1);
                matrix_multiply_func(A[count][x], P[count - 1][x - 1], Aux, K + 1, K + 1, K + 1);
                copy_matrix(A[count][x], Aux, K + 1);
            } else {
                copy_matrix(A[count][x], S[count - 1][x], K + 1);
            }
        }
        copy_matrix(P[count][0], A[count][0], K + 1);
        copy_matrix(S[count][K - 1], A[count][K - 1], K + 1);
        for (long long x = 1; x < K; x++)
            matrix_multiply_func(P[count][x - 1], A[count][x], P[count][x], K + 1, K + 1, K + 1);
        for (long long x = K - 2; x >= 0; x--)
            matrix_multiply_func(A[count][x], S[count][x + 1], S[count][x], K + 1, K + 1, K + 1);
        if (m > N / K) break;
    }
}

int main() {
    cin >> N >> K;
    Power[0] = 1;
    int i = 1;
    while (Power[i - 1] <= N / K) {
        Power[i] = Power[i - 1] * K;
        ++i;
    }
    int ind = i - 1;
    initializeA();
    long long init = N, last = -1, count = -1, ind2 = 0;
    Res[0][K] = 1;
    for (int i = ind; i >= 0; i--) {
        while (Power[i] <= init) {
            matrix_multiply_func(Res, A[i][ind2], Aux, K + 1, K + 1, K + 1);
            copy_matrix(Res, Aux, K + 1);
            ind2++;
            if (ind2 == K) ind2 = 0;
            init -= Power[i];
        }
    }
    long long ans = 0;
    for (int i = 0; i <= K; i++) mod_add(ans, Res[0][i]);
    cout << ans << "\n";
    return 0;
}
